import com.eyedrop.manager.*;
import org.json.*;
import java.time.*;
import java.util.*;
public class ConstraintsTest {
 static int checks;
 static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 static JSONObject task(String id,String profile,long at,int index,int count){return new JSONObject().put("id",id).put("drugId",profile).put("name",profile).put("profile",profile).put("day","2026-11-11").put("index",index).put("total",count).put("status","Pending").put("desired_epoch",at).put("scheduled_epoch",at).put("scheduled",Constraints.local(at)).put("fixed_interval",profile.equals("CYCLO")?720:0).put("care_seconds",profile.equals("CARE")?600:0).put("press_seconds",profile.equals("CARE")?180:0);}
 static JSONArray plan(long start,int tears){JSONArray a=new JSONArray();a.put(task("c1","CYCLO",start,1,2)).put(task("c2","CYCLO",start+43200,2,2));for(int i=0;i<3;i++)a.put(task("s"+i,"CARE",start+i*25200, i+1,3));for(int i=0;i<tears;i++)a.put(task("t"+i,"TEARS",start+Math.round(i*50400.0/(tears-1)),i+1,tears));return a;}
 public static void main(String[] args)throws Exception{
  long start=Constraints.epoch("2026-11-11T08:00"),end=start+50400;
  JSONObject c=task("c","CYCLO",start,1,2),t=task("t","TEARS",start,1,6),s=task("s","CARE",start,1,3);
  check(!Constraints.pair(c,start,t,start+899).isEmpty(),"899 seconds blocked");check(Constraints.pair(c,start,t,start+900).isEmpty(),"15 minutes boundary allowed");check(!Constraints.pair(c,start,t,start-899).isEmpty(),"before cyclosporine blocked");check(Constraints.pair(c,start,t,start-900).isEmpty(),"before exactly 15 min allowed");
  check(!Constraints.pair(s,start,t,start+599).isEmpty(),"care excludes 599 seconds");check(Constraints.pair(s,start,t,start+600).isEmpty(),"care ends at 600");check(!Constraints.pair(s,start,c,start).isEmpty(),"simultaneous dose excluded by care");check(Constraints.pair(c,start,s,start+60).isEmpty(),"no invented separation from other drops");
  check(!Constraints.pair(c,start,task("c2","CYCLO",start,2,2),start+43199).isEmpty(),"fixed interval second precision");check(Constraints.pair(c,start,task("c2","CYCLO",start,2,2),start+43200).isEmpty(),"exact 12h allowed");
  for(int count:new int[]{5,6}){Constraints.Result r=Constraints.solve(plan(start,count),new JSONArray(),start,end);check(r.conflicts.length()==0,"5/6 tears solution");check(r.plans.length()==count+5,"no extra doses");check(Constraints.validate(r.plans,new JSONArray(),start,end).length()==0,"all output constraints valid");}
  for(int n=0;n<30;n++){long begin=start+n*60;Constraints.Result r=Constraints.solve(plan(begin,6),new JSONArray(),begin,begin+50400);check(r.conflicts.length()==0,"offset scenario solvable");check(Constraints.validate(r.plans,new JSONArray(),begin,begin+50400).length()==0,"offset constraints valid");}
  Constraints.Result impossible=Constraints.solve(plan(start,6),new JSONArray(),start,start+3600);check(impossible.conflicts.length()>0,"short wake window explicit conflict");check(Constraints.validate(impossible.plans,new JSONArray(),start,start+3600).length()==0,"partial output never violates constraints");boolean unresolved=false;for(int i=0;i<impossible.plans.length();i++){JSONObject p=impossible.plans.getJSONObject(i);if(p.optString("status").equals("Unresolved")){unresolved=true;check(p.isNull("scheduled"),"unresolved not forced into a time");}}check(unresolved,"unresolved retained");
  JSONArray changed=plan(start,6);changed.getJSONObject(2).put("scheduled_epoch",start).put("scheduled",Constraints.local(start));check(Constraints.validate(changed,new JSONArray(),start,end).length()>0,"manual conflict identified");
  JSONObject pin=new JSONObject(c.toString()).put("actual",Constraints.local(start+300)).put("actual_epoch",start+300).put("status","Completed");JSONArray pending=new JSONArray().put(task("t2","TEARS",start+900,1,1));Constraints.Result pinned=Constraints.solve(pending,new JSONArray().put(pin),start,end);check(pinned.conflicts.length()==0,"can move around actual dose");check(Constraints.at(pinned.plans.getJSONObject(0))>=start+1200,"actual timestamp controls protection");check(pin.getLong("actual_epoch")==start+300,"actual immutable");
  Store store=new Store(null);JSONObject rx=new JSONObject().put("id","care").put("name","施图伦").put("count",3).put("active",true);Store.configure(rx,"CARE",0,0);store.drugs().put(rx);store.generate();String id=store.plans().getJSONObject(0).getString("id");long actual=store.start();store.completeAt(id,actual);store.completeAt(id,actual);check(store.records().length()==1&&store.cares().length()==1,"idempotent care start");JSONObject care=store.cares().getJSONObject(0);check(care.getLong("end_time")==actual+600,"10-minute actual care");check(care.getJSONArray("actions").getJSONObject(0).getInt("duration")==180,"press3min");store.tick(actual+179);check(care.getJSONArray("actions").getJSONObject(0).getString("status").equals("Running"),"press until second179");store.tick(actual+180);check(care.getJSONArray("actions").getJSONObject(0).getString("status").equals("Completed"),"press ends180");check(care.getJSONArray("actions").getJSONObject(1).getString("status").equals("Running"),"rest begins180");Store restored=new Store(store.data.toString());restored.tick(actual+600);check(restored.cares().getJSONObject(0).getString("status").equals("Completed"),"restart deadline recovered");check(restored.cares().getJSONObject(0).getJSONArray("actions").getJSONObject(1).getLong("completion_time")==actual+600,"action completion saved");
  restored.tick(actual-1);check(restored.cares().getJSONObject(0).getJSONArray("actions").getJSONObject(0).getString("status").equals("Completed"),"completed care does not rewind on clock change");
  String historical=restored.records().toString();restored.drugs().remove(0);restored.generate();check(restored.records().toString().equals(historical),"deletion never changes history");check(restored.cares().length()==1,"deletion retains care records");
  Store missed=new Store(null);JSONObject generic=new JSONObject().put("id","g").put("name","G").put("count",3).put("active",true);Store.configure(generic,"GENERAL",0,0);missed.drugs().put(generic);missed.generate();String first=missed.plans().getJSONObject(0).getString("id");missed.missed(first);missed.generate(true,missed.start()+600);check(missed.plans().length()==3,"missed not replaced");check(missed.records().getJSONObject(0).getString("status").equals("Missed"),"missed record");check(missed.cares().length()==0,"missed no care");
  Store overdue=new Store(null);overdue.drugs().put(new JSONObject(generic.toString()));overdue.generate();overdue.generate(true,overdue.endEpoch()+1);int review=0;for(int i=0;i<overdue.plans().length();i++)if(overdue.plans().getJSONObject(i).getString("status").equals("NeedsReview"))review++;check(review==3,"overdue never automatic catch-up");
  String old="{\"wake\":480,\"end\":1320,\"drugs\":[],\"plans\":[],\"records\":[{\"id\":\"old\",\"drugId\":\"x\",\"day\":\"2026-11-10\",\"name\":\"旧药\",\"scheduled\":\"2026-11-10T08:00\",\"actual\":\"2026-11-10T08:02\",\"status\":\"Completed\"}]}";Store migrated=new Store(old);check(migrated.records().getJSONObject(0).getString("original_scheduled").equals("2026-11-10T08:00"),"v0.1 original plan migration");check(migrated.records().getJSONObject(0).getString("actual").equals("2026-11-10T08:02"),"v0.1 actual preserved");
  System.out.println("PASS: "+checks+" constraint/care/migration assertions.");
 }
}
